import numpy as np
L=open('answer.xyz').read().split('\n')[2:];a=[l.split() for l in L if l.strip()]
X=np.array([[float(v) for v in r[1:]] for r in a]);
au=[i for i,r in enumerate(a) if r[0]=='Au'][0]
for i,r in enumerate(a):
  if r[0]=='Si': print(np.linalg.norm(X[i]-X[au]))
si=[i for i,r in enumerate(a) if r[0]=='Si']
v1=X[si[0]]-X[au];v2=X[si[1]]-X[au];print(np.degrees(np.arccos(v1@v2/np.linalg.norm(v1)/np.linalg.norm(v2))))
"
